// The current status of the migration.
type OnlineMigrationStatus string

const (
	OnlineMigrationStatusRunning  OnlineMigrationStatus = "running"
	OnlineMigrationStatusSyncing  OnlineMigrationStatus = "syncing"
	OnlineMigrationStatusCanceled OnlineMigrationStatus = "canceled"
	OnlineMigrationStatusError    OnlineMigrationStatus = "error"
	OnlineMigrationStatusDone     OnlineMigrationStatus = "done"
)

func NewOnlineMigrationStatusFromString(s string) (OnlineMigrationStatus, error) {
	switch s {
	case "running":
		return OnlineMigrationStatusRunning, nil
	case "syncing":
		return OnlineMigrationStatusSyncing, nil
	case "canceled":
		return OnlineMigrationStatusCanceled, nil
	case "error":
		return OnlineMigrationStatusError, nil
	case "done":
		return OnlineMigrationStatusDone, nil
	}
	var t OnlineMigrationStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (o OnlineMigrationStatus) Ptr() *OnlineMigrationStatus {
	return &o
}

